<script>
(()=>{const selected=new Map(),fare={{(float)$departure->fare}},passengers=document.getElementById('passengers'),labels=document.getElementById('selectedLabels'),total=document.getElementById('totalAmount'),fareLine=document.getElementById('fareLine'),submit=document.getElementById('submitButton'),holderName=document.querySelector('[name=contact_name]'),holderDocument=document.querySelector('[name=contact_document]');
function render(){const list=[...selected.entries()],docType=document.getElementById('holderDocumentType'),extraHeading=document.getElementById('additionalHeading');labels.innerHTML=list.length?list.map(([id,code])=>`<span class="rounded-xl bg-[#062c21] px-2.5 py-1 text-sm font-bold text-amber-300">Asiento ${code}</span>`).join(''):'<span class="text-sm font-semibold text-amber-800">Selecciona un asiento en el croquis.</span>';extraHeading.classList.toggle('hidden',list.length<2);extraHeading.classList.toggle('flex',list.length>1);passengers.innerHTML=list.map(([id,code],i)=>{if(i===0)return `<input type="hidden" name="seats[]" value="${id}"><input type="hidden" class="primary-name" name="passengers[0][name]"><input type="hidden" class="primary-document" name="passengers[0][document]"><input type="hidden" class="primary-document-type" name="passengers[0][document_type]"><input type="hidden" name="passengers[0][age]" value="">`;return `<div class="passenger-card"><div class="flex items-center justify-between"><strong class="text-sm text-slate-950">Asiento ${code}</strong><span class="rounded-md bg-amber-50 px-2 py-0.5 text-xs font-semibold text-amber-800">Pasajero ${i+1}</span></div><input type="hidden" name="seats[]" value="${id}"><div class="mt-1.5 grid gap-1.5 sm:grid-cols-2"><div class="field"><label>Tipo de documento</label><select name="passengers[${i}][document_type]"><option>DNI</option><option>CE</option><option>Pasaporte</option></select></div><div class="field"><label>Número</label><input required name="passengers[${i}][document]"></div><div class="field sm:col-span-2"><label>Nombres y apellidos</label><input required name="passengers[${i}][name]"></div><input type="hidden" name="passengers[${i}][age]" value=""></div></div>`}).join('');const syncPrimary=()=>{passengers.querySelector('.primary-name')?.setAttribute('value',holderName.value);passengers.querySelector('.primary-document')?.setAttribute('value',holderDocument.value);passengers.querySelector('.primary-document-type')?.setAttribute('value',docType.value)};syncPrimary();const amount=list.length*fare;fareLine.textContent=`${list.length} × S/ ${fare.toFixed(2)}`;total.textContent=`S/ ${amount.toFixed(2)}`;submit.textContent=list.length?`Continuar · S/ ${amount.toFixed(2)}`:'Selecciona un asiento';submit.disabled=!list.length}
document.querySelectorAll('.seat-btn:not(:disabled)').forEach(button=>button.addEventListener('click',()=>{const id=button.dataset.seatId;if(selected.has(id)){selected.delete(id);button.classList.remove('selected')}else if(selected.size<4){selected.set(id,button.dataset.code);button.classList.add('selected')}render()}));document.querySelectorAll('[data-deck-tab]').forEach(button=>button.addEventListener('click',()=>{const deck=button.dataset.deckTab;document.querySelectorAll('[data-deck-panel]').forEach(panel=>panel.hidden=panel.dataset.deckPanel!==deck);document.querySelectorAll('[data-deck-tab]').forEach(tab=>{const active=tab.dataset.deckTab===deck;tab.classList.toggle('bg-white',active);tab.classList.toggle('text-slate-900',active);tab.classList.toggle('shadow-sm',active);tab.classList.toggle('text-slate-500',!active)})}));document.querySelector('[data-deck-tab]')?.click();[holderName,holderDocument].forEach(field=>field.addEventListener('input',()=>{passengers.querySelector('.primary-name')?.setAttribute('value',holderName.value);passengers.querySelector('.primary-document')?.setAttribute('value',holderDocument.value)}));document.getElementById('holderDocumentType').addEventListener('change',event=>passengers.querySelector('.primary-document-type')?.setAttribute('value',event.target.value));render()})();
</script>
